const user = { name: "Ana", age: 30 };
const { name, role = "dev" } = user;
const [first, ...rest] = [1, 2, 3];

const older = { ...user, age: 31 }; // novo objeto
const all = [...rest, 4];           // [2, 3, 4]

function createCounter() {
  let count = 0;
  return {
    increment: () => ++count,
    current: () => count,
  };
}

const counter = createCounter();
counter.increment();
counter.current(); // 1

class Timer {
  seconds = 0;
  startBroken() {
    setTimeout(function () {
      this.seconds++; // TypeError: this é undefined
    }, 1000);
  }
  start() {
    setTimeout(() => {
      this.seconds++; // this é a instância
    }, 1000);
  }
}

const original = { name: "Ana", address: { city: "Recife" } };

const shallow = { ...original };
shallow.address.city = "Natal";
original.address.city; // "Natal" (compartilhado)

const deep = structuredClone(original);
deep.address.city = "Olinda";
original.address.city; // continua "Natal"

class Animal {
  constructor(name) { this.name = name; }
  speak() { return `${this.name} faz barulho`; }
}

// equivalente sem class
function Animal2(name) { this.name = name; }
Animal2.prototype.speak = function () {
  return `${this.name} faz barulho`;
};

Object.getPrototypeOf(new Animal("Rex")) === Animal.prototype; // true
